var _idiomIndex = null;

/* 첫 낱말로 묶어 둔다. 본문을 훑으며 후보를 빠르게 좁히기 위해서다.
   긴 숙어를 먼저 맞춰 본다 — 'a case in point' 가 'a case' 보다 앞서야 한다. */
function _buildIdiomIndex() {
    var idx = {};
    Object.keys(window.VOCAB_IDIOMS).forEach(function (phrase) {
        var parts = phrase.split(' ').filter(Boolean);
        var first = parts[0];
        if (!first || first === '~') return;
        (idx[first] = idx[first] || []).push({ phrase: phrase, parts: parts });
    });
    Object.keys(idx).forEach(function (k) {
        idx[k].sort(function (a, b) { return b.parts.length - a.parts.length; });
    });
    return idx;
}

/* 같은 낱말을 여러 번 되돌리지 않도록 한 번 구한 것은 들고 있는다 */
var _infCache = {};
function _inflectionsOf(w) {
    if (!_infCache[w]) _infCache[w] = [w].concat(window.vocabInflectClosure(w));
    return _infCache[w];
}

function _tokenMatches(textTok, patTok) {
    if (textTok === patTok) return true;
    return _inflectionsOf(textTok).indexOf(patTok) !== -1;
}

/* 본문 toks 의 i 번째부터 숙어 parts 가 들어맞는지 본다.
   맞으면 끝난 자리를, 아니면 -1 을 돌려준다. */
function _matchIdiomAt(toks, i, parts) {
    var t = i, p = 0;
    while (p < parts.length) {
        if (parts[p] === '~') {
            p++;
            if (p >= parts.length) return t;      // 물결로 끝나면 여기까지
            var target = parts[p], found = -1;
            var stop = Math.min(t + 4, toks.length);   // 목적어는 길어야 서너 낱말
            for (var k = t; k < stop; k++) {
                if (_tokenMatches(toks[k], target)) { found = k; break; }
            }
            if (found < 0) return -1;
            t = found + 1; p++;
            continue;
        }
        if (t >= toks.length || !_tokenMatches(toks[t], parts[p])) return -1;
        t++; p++;
    }
    return t;
}

/* 본문에서 아는 숙어를 찾아 돌려준다.
   겹쳐 잡지 않는다 — 한 번 걸린 자리는 건너뛴다. */
window.vocabFindIdioms = function (text) {
    if (!_idiomIndex) _idiomIndex = _buildIdiomIndex();

    var toks = String(text || '').toLowerCase()
                 .replace(/[\u2018\u2019]/g, "'")
                 .match(/[a-z']+/g) || [];

    var out = [], seen = {};
    for (var i = 0; i < toks.length; i++) {
        var cands = _idiomIndex[toks[i]];
        if (!cands) {
            // 굴절형으로 나왔을 수 있다 (took → take)
            var forms = _inflectionsOf(toks[i]);
            for (var f = 1; f < forms.length && !cands; f++) cands = _idiomIndex[forms[f]];
        }
        if (!cands) continue;

        for (var c = 0; c < cands.length; c++) {
            var end = _matchIdiomAt(toks, i, cands[c].parts);
            if (end > i) {
                var ph = cands[c].phrase;
                if (!seen[ph]) {
                    seen[ph] = true;
                    out.push({ phrase: ph, meaning: window.VOCAB_IDIOMS[ph] });
                }
                i = end - 1;
                break;
            }
        }
    }
    return out;
};
